from pathlib import Path
import re,html
r=Path('public/studio')
nav=[('index.html','Home'),('websites.html','Websites'),('how-it-works.html','How it works'),('about.html','About')]
def page(file,title,body,extra=''):
 links=''.join(f'<a href="/studio/{p}"'+(' aria-current="page"' if p==file else '')+f'>{label}</a>' for p,label in nav)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#f5f6f2"><meta name="robots" content="noindex,follow"><meta name="description" content="Solborne helps businesses turn their story into a clear, considered website. Explore the work, process and free first-website scope."><title>{title} | Solborne &amp; Co.</title><link rel="icon" href="/assets/bearing.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/public-sans-latin-wght-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/studio/reboot.css"><link rel="stylesheet" href="/studio/design.css"><script src="/studio/design.js" defer></script>{extra}</head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/studio/index.html" aria-label="Solborne home"><img src="/assets/bearing.svg" alt="" width="25" height="30"><img src="/assets/solborne-wordmark.svg" alt="Solborne & Co." width="155" height="28"></a><button class="menu" aria-expanded="false" aria-controls="site-nav" hidden>Menu</button><nav id="site-nav" aria-label="Main navigation">{links}<a class="button small" href="/studio/start.html">Start your website</a></nav></header><main id="main">{body}</main><footer class="footer"><div class="footer-top"><div><img src="/assets/solborne-wordmark.svg" alt="Solborne & Co." width="180" height="35"><p>A place for every business.</p></div><div><a href="/studio/websites.html">Explore websites</a><a href="/studio/how-it-works.html">Our process</a><a href="/walk/">Website editor</a><a href="/versions.html">Your saved websites</a></div><div><a href="/studio/contact.html">Contact & complaints</a><a href="/studio/offer.html">Offer & delivery scope</a><a href="/studio/privacy.html">Privacy & data handling</a><a href="/studio/terms.html">Service terms</a></div></div><div class="legal"><p>Solborne is a brand of KISNO PROPTY LLP. LLPIN ACK-0281. Registered in India with limited liability.</p><p>Registered office: 22 Kalakar Street, Kolkata, West Bengal 700007, India.</p><p>Design preview · <a href="/">View the current website</a></p></div></footer></body></html>'''
def save(file,title,body,extra=''):(r/file).write_text(page(file,title,body,extra),encoding='utf-8')
def office(theme='atelier',small=False):
 return f'''<div class="office {theme}" aria-label="Illustrative business website, not a customer testimonial"><div class="chrome"><span></span><span></span><span></span><b>your-business.solborne.in</b></div><div class="office-bar"><strong class="demo-name">The Good Workshop</strong><span>Work &nbsp; About &nbsp; Contact</span></div><div class="office-main"><div><p class="demo-label">Furniture made to belong.</p><p class="demo-heading">Good things.<br>Built to last.</p><p class="demo-copy">Thoughtful furniture, made by hand.<br>For the places you call your own.</p><span class="demo-pill">Explore our work</span></div><div class="sculpture" aria-hidden="true"><div class="arch"></div><div class="sphere"></div><div class="plinth"></div><div class="caption">Materials. Craft. Care.</div></div></div><div class="office-bottom"><span>Made with care</span><span>Designed around you</span><span>A real place to begin</span></div></div>'''
home=f'''<section class="hero container"><div class="hero-copy"><p class="intro">For businesses ready to be seen.</p><h1>Your business.<br>A place of<br>its own.</h1><p class="lead">A considered website that feels like you. Clear, beautiful and ready to share with the people who matter.</p><div class="actions"><a class="button" href="/studio/start.html">Start your website</a><a class="text-link" href="/studio/websites.html">Explore the possibilities <span aria-hidden="true">↗</span></a></div><p class="quiet">Your first static website draft is free. <a href="/studio/offer.html">See the scope</a>.</p></div><div class="hero-art">{office()}<p class="art-note">An illustrative design. Your story shapes yours.</p></div></section><section class="manifest container"><p class="intro">Your digital office</p><h2>A website should feel<br>like walking into your business.</h2><p>People should understand what you do, find what they need, and know how to reach you. We make room for all three.</p><div class="three"><article><span class="symbol" aria-hidden="true">◌</span><h3>Your identity</h3><p>Your logo, your language, your character. A presence built around the business you have made.</p></article><article><span class="symbol" aria-hidden="true">▤</span><h3>Your information</h3><p>Services, work, the people behind it and practical answers. Organised so visitors can find their way.</p></article><article><span class="symbol" aria-hidden="true">↗</span><h3>Your next conversation</h3><p>A clear contact path. The right public details, presented with care.</p></article></div></section><section class="showcase"><div class="container"><div class="section-head"><div><p class="intro">Different businesses. Different expressions.</p><h2>Find your kind of presence.</h2></div><a href="/studio/websites.html" class="text-link">Explore the collection ↗</a></div><div class="showcase-grid"><a class="sample sage" href="/studio/example-workshop.html"><div class="sample-window"><p>The Good Workshop</p><h3>Made well.<br>Made yours.</h3><div class="mini-chair" aria-hidden="true"></div></div><div class="sample-meta"><span>Craft & interiors</span><span>View concept ↗</span></div></a><a class="sample blue" href="/studio/example-advisory.html"><div class="sample-window"><p>Northline Advisory</p><h3>A clearer view<br>of what’s next.</h3><div class="mini-lines" aria-hidden="true"></div></div><div class="sample-meta"><span>Professional services</span><span>View concept ↗</span></div></a><a class="sample rose" href="/studio/example-studio.html"><div class="sample-window"><p>Form & Field</p><h3>Spaces for<br>real life.</h3><div class="mini-room" aria-hidden="true"></div></div><div class="sample-meta"><span>Design & architecture</span><span>View concept ↗</span></div></a></div><p class="quiet">Illustrative concepts, not client projects or proof of results.</p></div></section><section class="process-feature container"><div><p class="intro">The Walk of Fame</p><h2>You know your business.<br>We help you tell its story.</h2><p class="lead">Start with what you know. We turn the right questions into a clear website brief, then into a design you can review.</p><a href="/studio/how-it-works.html" class="text-link">See how it works ↗</a></div><ol class="process-list"><li><span>1</span><div><h3>Find the story</h3><p>What you do, who you help, and what makes your business yours.</p></div></li><li><span>2</span><div><h3>Give it a shape</h3><p>Relevant pages, useful information, your brand and public disclosures.</p></div></li><li><span>3</span><div><h3>Make it yours</h3><p>Review the facts and design. Refine the colours, images and wording.</p></div></li></ol></section><section class="closing container"><p class="intro">Start where you are.</p><h2>A first website.<br>Or a better next one.</h2><p>Whether you are building a presence from nothing or rethinking an existing site, begin with your story.</p><a class="button" href="/studio/start.html">Let’s begin</a></section>'''
save('index.html','A place for your business',home)
save('websites.html','Websites',f'''<section class="page-hero container"><p class="intro">The website collection</p><h1>One business.<br>Many ways to show it.</h1><p class="lead">Your industry gives us a starting point. Your identity makes the final design yours.</p></section><section class="container"><div class="design-selector" aria-label="Website concept selector"><button data-theme="atelier" aria-pressed="true">Craft & interiors</button><button data-theme="advisory" aria-pressed="false">Professional services</button><button data-theme="creative" aria-pressed="false">Design studios</button></div><div class="interactive-office">{office()}</div><p class="quiet">Try a different direction. These are illustrative concepts, with no live enquiry collection.</p></section><section class="container collection"><a href="/studio/example-workshop.html"><span>Craft & interiors</span><h2>A place for your work.</h2><p>Bring materials, services and the maker’s story together.</p><b>Explore the workshop concept ↗</b></a><a href="/studio/example-advisory.html"><span>Professional services</span><h2>Clarity builds confidence.</h2><p>Explain your services, approach and how a client can begin.</p><b>Explore the advisory concept ↗</b></a><a href="/studio/example-studio.html"><span>Design & architecture</span><h2>Let the work breathe.</h2><p>Show your point of view with room for visual detail.</p><b>Explore the studio concept ↗</b></a></section><section class="closing container"><h2>A website, with room<br>for the whole business.</h2><p>Home, services, work, about and contact can each have a place where the available content supports it. The current free editor produces one page; a larger website is separately scoped.</p><a class="button" href="/studio/start.html">Find your direction</a></section>''')
save('how-it-works.html','How it works','''<section class="page-hero container"><p class="intro">The Walk of Fame</p><h1>From your story<br>to your website.</h1><p class="lead">A thoughtful process. Clear decisions. You stay in control of what represents your business.</p></section><section class="container journey"><article><span>01</span><div><h2>Tell us what you do.</h2><p>Who do you help? What do they need? We capture your services, audience and the character of the business. You can start from an existing website.</p></div></article><article><span>02</span><div><h2>Choose what belongs online.</h2><p>Confirm public contact details, operator identity, permissions for your assets, and the relevant service and privacy notices. Your private registration email stays private.</p></div></article><article><span>03</span><div><h2>Give the story a visual direction.</h2><p>A relevant layout, considered type and your actual brand. The free editor currently creates a single-page draft; additional pages and design work are separately scoped.</p></div></article><article><span>04</span><div><h2>Review before release.</h2><p>Check the public facts and preview, then submit for private review. Source files are available after release. Submission does not automatically publish a website.</p></div></article></section><section class="container split-callout"><div><h2>Prefer a conversation?</h2><p>The guided AI Walk is embedded. Its Gemini connection is awaiting activation. Until then, the website editor remains available.</p><a class="text-link" href="/ai-walk.html">View the guided Walk ↗</a></div><div><h2>Already have a brief?</h2><p>Save your basic details, open the canvas and use the existing editor to prepare and review your public website facts.</p><a class="text-link" href="/studio/start.html">Open your Walk ↗</a></div></section>''')
save('about.html','About Solborne','''<section class="page-hero container"><p class="intro">Why Solborne exists</p><h1>Every business<br>deserves a place.</h1><p class="lead">A website is your digital office. A place people can visit, understand your work, and begin a conversation.</p></section><section class="about-statement container"><div class="bearing-art" aria-hidden="true"><img src="/assets/bearing.svg" width="130" height="160" alt=""></div><div><h2>Built around the business.<br>Not the template.</h2><p>We begin with the people, services and ideas behind your business. Design follows that understanding: what visitors need to know, what deserves attention and how it should feel.</p><p>Templates and components can help us move faster. They are starting material, chosen for their quality and rights, then shaped into a coherent identity.</p></div></section><section class="container three principles"><article><h3>Make it clear.</h3><p>A visitor should understand your business and find the next useful step.</p></article><article><h3>Make it yours.</h3><p>Preserve your brand. Choose the structure and expression that fit your work.</p></article><article><h3>Make it usable.</h3><p>Readable on a phone. Reachable by keyboard. Motion that supports the experience.</p></article></section><section class="closing container"><h2>A presence first.<br>More useful work next.</h2><p>The free first website introduces your business. Acquisition, operational automations, ads, CRM and additional work are separately scoped paid services.</p><a class="button" href="/studio/start.html">Start with your story</a></section>''')
# Extract complete nested registration section, retaining the existing tested control IDs and backend.
s=Path('public/index.html').read_text(encoding='utf-8');start=s.find('<section class="section wrap registration-section"');depth=0;end=None
for match in re.finditer(r'<section\b[^>]*>|</section>',s[start:]):
 depth+=1 if not match.group().startswith('</') else -1
 if depth==0:end=start+match.end();break
fragment=s[start:end].replace('section wrap registration-section','container registration-section').replace('Solborne’s separate Cloudflare registration store','Solborne’s private Cloudflare and Supabase presales stores').replace('Solborne�s separate Cloudflare registration store','Solborne’s private Cloudflare and Supabase presales stores')
fragment=fragment.replace('�','’').replace('Preparing secure form’','Preparing secure form…')
save('start.html','Start your website','<section class="page-hero container compact"><p class="intro">Your first step</p><h1>Let’s make room<br>for your business.</h1><p class="lead">Save your details, then tell us your story. Your existing registration and private website workspace work here too.</p></section>'+fragment,'<script src="/registration.js" defer></script>')
# Present owned factual policy text in new original chrome. No HTML5 UP styling/code dependencies.
for name,title in [('privacy.html','Privacy & data handling'),('offer.html','Offer & delivery scope'),('contact.html','Contact & complaints'),('terms.html','Service terms')]:
 p=Path('public')/name
 if not p.exists():continue
 old=p.read_text(encoding='utf-8');match=re.search(r'<main[^>]*>(.*?)</main>',old,re.S)
 content=match.group(1) if match else '<h1>'+title+'</h1>'
 content=re.sub(r'<p class="eyebrow">.*?</p>','',content,flags=re.S)
 save(name,title,'<section class="container legal-content">'+content+'</section>')
# Original illustrative portfolio pages; real navigation, no fabricated testimonials/contact promises.
for file,name,tagline,desc,theme in [('example-workshop.html','The Good Workshop','Good things. Built to last.','An illustrative furniture workshop: custom pieces, restoration and a story about craft.','atelier'),('example-advisory.html','Northline Advisory','A clearer view of what’s next.','An illustrative professional-services practice: a clear offer, considered process and straightforward contact path.','advisory'),('example-studio.html','Form & Field','Spaces for real life.','An illustrative design studio: interiors, spatial planning and a portfolio-first presence.','creative')]:
 save(file,name,f'''<section class="container concept-notice"><p>Illustrative business concept · no real client or enquiry collection</p><a href="/studio/websites.html">Back to websites</a></section><section class="concept-hero container {theme}"><p class="intro">{name}</p><h1>{tagline}</h1><p class="lead">{desc}</p><a class="button" href="#concept-services">Explore the concept</a><div class="concept-visual" aria-hidden="true"><div class="arch"></div><div class="sphere"></div><div class="plinth"></div></div></section><section id="concept-services" class="container three"><article><h2>Services</h2><p>A place to explain the core services in the business’s own language.</p></article><article><h2>Our approach</h2><p>Useful detail about what a customer can expect and how the work begins.</p></article><article><h2>About the business</h2><p>The people and perspective behind the work, without invented claims.</p></article></section><section class="closing container"><h2>Your business could<br>look like you.</h2><p>Use this direction as a starting point. Your real brand, content and verified disclosures make the final website yours.</p><a class="button" href="/studio/start.html">Create your own brief</a></section>''')
print('Created',len(list(r.glob('*.html'))),'original multipage design preview pages.')
